def solve(g):
    n=len(g); m=len(g[0])
    g=[row[:] for row in g]
    changed=True
    def val(r,c): return g[r][c]
    while changed:
        changed=False
        # horizontal mirror pairs and vertical mirror pairs: if one is 3 (or not yet resolved) and other has a value, propagate.
        cells={}
        for r in range(n):
            for c in range(m):
                cells[(r,c)]=g[r][c]
        for r in range(n):
            for c in range(m//2):
                a,b=(r,c),(r,m-1-c)
                x,y=val(r,a),val(r,b)
                if x==3 and y!=3: cells[a]=y; changed=True
                if y==3 and x!=3: cells[b]=x; changed=True
        for c in range(m):
            for r in range(n//2):
                a,b=(r,c),(n-1-r,c)
                x,y=val(a),val(b)
                if x==3 and y!=3: cells[a]=y; changed=True
                if y==3 and x!=3: cells[b]=x; changed=True
    return [[cells.get((r,c),g[r][c]) for c in range(m)] for r in range(n)]
